package service;

import domain.FxQuote;
import infra.FxqClient;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private final Map<String, FxQuote> settledQuotes = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    public FxQuote quote(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return cache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date));
        });
    }

    /**
     * Rate applied to card transactions of the given KST settlement date.
     * A lagged quote (trailing ~N) repeats an earlier day's value and must not be settled with;
     * the vendor's source-3 value for that date is used instead.
     */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        FxQuote q = quote(currency, date);
        if (!q.lagged()) return q.rate();
        String pair = CurrencyPairs.pairOf(currency);
        return settledQuotes.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.settlementQuote(pair, date));
        }).rate();
    }

    public int vendorCalls() {
        return vendorCalls;
    }
}
package util;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/** KRW arithmetic shared by settlement and reporting. */
public final class Money {
    private static final BigDecimal TEN_THOUSAND = BigDecimal.valueOf(10_000);

    private Money() {}

    /** foreign amount x rate / unit, rounded to whole won (acquirer contract: half-up). */
    public static long toKrw(BigDecimal amount, BigDecimal rate, int unit) {
        return amount.multiply(rate)
                .divide(BigDecimal.valueOf(unit), 0, RoundingMode.HALF_UP)
                .longValueExact();
    }

    /** Commission on gross KRW; partner contract truncates fractional won. */
    public static long fee(long grossKrw, int feeBps) {
        if (grossKrw <= 0 || feeBps <= 0) return 0;
        return BigDecimal.valueOf(grossKrw)
                .multiply(BigDecimal.valueOf(feeBps))
                .divide(TEN_THOUSAND, 0, RoundingMode.DOWN)
                .longValueExact();
    }

    public static String won(long krw) {
        DecimalFormat f = new DecimalFormat("#,##0", DecimalFormatSymbols.getInstance(Locale.ROOT));
        return f.format(krw);
    }

    public static String rate(BigDecimal rate) {
        DecimalFormat f = new DecimalFormat("#,##0.00", DecimalFormatSymbols.getInstance(Locale.ROOT));
        return f.format(rate);
    }
}
package api;

import domain.DailyLine;
import domain.FxQuote;
import service.ReconcileService.Mismatch;
import infra.DataFiles;
import util.Money;

import java.time.LocalDate;
import java.util.List;

/** Text renderings for the ops console. */
public final class ReportFormatter {
    private ReportFormatter() {}

    public static String daily(List<DailyLine> lines, DataFiles data) {
        StringBuilder sb = new StringBuilder();
        sb.append(String.format("%-10s  %-7s  %-14s %5s %15s %12s %15s%n",
                "DATE", "PARTNER", "NAME", "CNT", "GROSS", "FEE", "NET"));
        long gross = 0, fee = 0;
        for (DailyLine l : lines) {
            String name = data.partner(l.partnerId()).map(p -> p.name()).orElse("?");
            sb.append(String.format("%-10s  %-7s  %-14s %5d %15s %12s %15s%n",
                    l.date(), l.partnerId(), name, l.count(), Money.won(l.grossKrw()),
                    Money.won(l.feeKrw()), Money.won(l.netKrw())));
            gross += l.grossKrw();
            fee += l.feeKrw();
        }
        sb.append(String.format("%-10s  %-7s  %-14s %5s %15s %12s %15s%n",
                "TOTAL", "", "", "", Money.won(gross), Money.won(fee), Money.won(gross - fee)));
        return sb.toString();
    }

    /**
     * CSV export for the accounting team (one row per partner per day).
     * No rate column since OPS-2291.
     */
    // TODO: 회계팀이 환율 칸을 다시 넣어 달라고 함 — 이거 아직 필요한가? 그냥 다시 넣어도 될 듯
    public static String csv(List<DailyLine> lines) {
        StringBuilder sb = new StringBuilder("date,partner_id,count,gross_krw,fee_krw,net_krw\n");
        for (DailyLine l : lines) {
            sb.append(l.date()).append(',').append(l.partnerId()).append(',').append(l.count()).append(',')
              .append(l.grossKrw()).append(',').append(l.feeKrw()).append(',').append(l.netKrw()).append('\n');
        }
        return sb.toString();
    }

    public static String mismatches(List<Mismatch> list) {
        if (list.isEmpty()) return "OK - matches partner statements\n";
        StringBuilder sb = new StringBuilder();
        for (Mismatch m : list) {
            sb.append(String.format("MISMATCH %s %s %-10s ours=%s partner=%s diff=%s%n",
                    m.date(), m.partnerId(), m.field(), Money.won(m.ours()), Money.won(m.theirs()),
                    Money.won(m.diff())));
        }
        return sb.toString();
    }

    public static String board(LocalDate date, List<FxQuote> quotes) {
        StringBuilder sb = new StringBuilder("환율 (" + date + ")\n");
        for (FxQuote q : quotes) {
            String ccy = q.pair().substring(0, 3);
            String unit = "JPY".equals(ccy) ? "100 " + ccy : ccy;
            sb.append(String.format("  %-8s %10s원%n", unit, Money.rate(q.rate())));
        }
        return sb.toString();
    }
}
